#!/usr/bin/env bash
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
APP_NAME="Magpie"
VERSION="4.0.0"
DIST_DIR="$ROOT_DIR/dist"
APP_DIR="$DIST_DIR/$APP_NAME.app"
CONTENTS_DIR="$APP_DIR/Contents"
MACOS_DIR="$CONTENTS_DIR/MacOS"
RESOURCES_DIR="$CONTENTS_DIR/Resources"
ICONSET_DIR="$ROOT_DIR/.build/magpie.iconset"

echo "==> Baking repo path: $ROOT_DIR"
ESCAPED_REPO="${ROOT_DIR//\\/\\\\}"
ESCAPED_REPO="${ESCAPED_REPO//\"/\\\"}"
mkdir -p "$ROOT_DIR/app/Sources/Magpie"
cat > "$ROOT_DIR/app/Sources/Magpie/BakedRepoPath.swift" <<EOF
// Generated by scripts/build_app.sh. Do not edit by hand.
let bakedRepoPath = "$ESCAPED_REPO"
EOF

echo "==> Building magpie-helper"
swift build -c release --package-path "$ROOT_DIR/helper"

echo "==> Building Magpie app"
swift build -c release --package-path "$ROOT_DIR/app"

echo "==> Assembling $APP_DIR"
rm -rf "$APP_DIR"
mkdir -p "$MACOS_DIR" "$RESOURCES_DIR"

cp "$ROOT_DIR/app/.build/release/Magpie" "$MACOS_DIR/Magpie"
cp "$ROOT_DIR/helper/.build/release/magpie-helper" "$RESOURCES_DIR/magpie-helper"
chmod +x "$MACOS_DIR/Magpie" "$RESOURCES_DIR/magpie-helper"

ICON_KEY=""
if command -v rsvg-convert >/dev/null 2>&1 \
    && command -v iconutil >/dev/null 2>&1 \
    && [[ -f "$ROOT_DIR/magpie/static/icon.svg" ]]; then
    echo "==> Converting icon.svg to Magpie.icns"
    rm -rf "$ICONSET_DIR"
    mkdir -p "$ICONSET_DIR"
    for base in 16 32 128 256 512; do
        rsvg-convert -w "$base" -h "$base" \
            "$ROOT_DIR/magpie/static/icon.svg" \
            -o "$ICONSET_DIR/icon_${base}x${base}.png"
        double=$((base * 2))
        rsvg-convert -w "$double" -h "$double" \
            "$ROOT_DIR/magpie/static/icon.svg" \
            -o "$ICONSET_DIR/icon_${base}x${base}@2x.png"
    done
    if iconutil -c icns "$ICONSET_DIR" -o "$RESOURCES_DIR/Magpie.icns"; then
        ICON_KEY='<key>CFBundleIconFile</key><string>Magpie</string>'
    else
        echo "==> iconutil failed; continuing without an app icon"
        rm -f "$RESOURCES_DIR/Magpie.icns"
    fi
else
    echo "==> Skipping icon conversion (rsvg-convert/iconutil not available)"
fi

echo "==> Writing Info.plist"
cat > "$CONTENTS_DIR/Info.plist" <<EOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>CFBundleDevelopmentRegion</key>
    <string>en</string>
    <key>CFBundleDisplayName</key>
    <string>$APP_NAME</string>
    <key>CFBundleExecutable</key>
    <string>Magpie</string>
    <key>CFBundleIdentifier</key>
    <string>ai.magpie.app</string>
    <key>CFBundleInfoDictionaryVersion</key>
    <string>6.0</string>
    <key>CFBundleName</key>
    <string>$APP_NAME</string>
    <key>CFBundlePackageType</key>
    <string>APPL</string>
    <key>CFBundleShortVersionString</key>
    <string>$VERSION</string>
    <key>CFBundleVersion</key>
    <string>$VERSION</string>
    $ICON_KEY
    <key>LSMinimumSystemVersion</key>
    <string>14.0</string>
    <key>LSUIElement</key>
    <true/>
    <key>NSPrincipalClass</key>
    <string>NSApplication</string>
    <key>NSHighResolutionCapable</key>
    <true/>
    <key>NSMicrophoneUsageDescription</key>
    <string>Magpie records your microphone during meetings you choose to record.</string>
    <key>NSCalendarsFullAccessUsageDescription</key>
    <string>Magpie reads your calendar to title meetings and include events in your journal.</string>
    <key>NSRemindersFullAccessUsageDescription</key>
    <string>Magpie creates reminders from your open loops.</string>
    <key>NSAppleEventsUsageDescription</key>
    <string>Magpie can create a visible Mail draft when you ask it to.</string>
    <key>NSScreenCaptureUsageDescription</key>
    <string>Magpie captures your screen so it can remember what you worked on.</string>
    <key>NSAppTransportSecurity</key>
    <dict>
        <key>NSAllowsLocalNetworking</key>
        <true/>
    </dict>
</dict>
</plist>
EOF

echo "==> Ad-hoc signing"
codesign --force --deep -s - "$APP_DIR"

echo "==> Built $APP_DIR"
